const items = $input.all();
const output = [];

for (const item of items) {
  const d = item.json;

  // Skip already-processed rows
  if (d['Status'] && d['Status'].trim() !== '') continue;

  // Skip ghost/empty rows
  const rawEmail = d['Email Address'] || d['Email'] || d['email'] || '';
  if (!rawEmail.trim()) continue;

  // Detect role
  const isSWE = !!(d['Primary Programming Languages'] || d['GitHub Profile URL']);
  const role  = isSWE ? 'SWE' : 'BDM';

  // Normalize fields
  const name      = d['Full Name']            || d['Applicant Name'] || d['Name'] || '';
  const email     = d['Email Address']        || d['Email']          || '';
  const phone     = d['Phone Number']         || d['Phone']          || '';
 const resumeUrl = d['Upload Your Resume'] || 
                  d['Resume Link']        || 
                  d['Resume/CV']          || 
                  d['Resume']             ||  // <- ADD THIS
                  d['CV']                || 
                  '';
  const linkedin  = d['LinkedIn Profile URL'] || d['LinkedIn']       || '';
  const expYears  = d['Years of Experience']  || d['Experience']     || '';
  const extra1    = isSWE ? (d['Primary Programming Languages'] || '') : (d['Industry Experience'] || '');
  const extra2    = isSWE ? (d['GitHub Profile URL'] || '')            : (d['Largest Deal Closed (USD)'] || '');

  const candidateId = role + '_' + Date.now() + '_' + Math.random().toString(36).slice(2,7).toUpperCase();

  output.push({ json: {
    candidateId, name, email, phone, role,
    resumeUrl, linkedin, expYears, extra1, extra2
  }});
}

return output;

const items = $input.all();
const output = [];

for (const item of items) {
  let url = item.json.resumeUrl || '';
  let fileId = '';
  url = url.trim();

  let match = url.match(/[?&]id=([a-zA-Z0-9_\-]+)/);
  if (match) {
    fileId = match[1];
  }

  if (!fileId) {
    match = url.match(/\/d\/([a-zA-Z0-9_\-]+)/);
    if (match) fileId = match[1];
  }

  const downloadUrl = fileId 
    ? `https://drive.google.com/uc?export=download&id=${fileId}`
    : url;

  output.push({ 
    json: {
      ...item.json,
      resumeDownloadUrl: downloadUrl,
      driveFileId: fileId || ''
    } 
  });
}

return output;

const items = $input.all();
const output = [];
const normalized = $('Normalize Application Data').all();

for (let i = 0; i < items.length; i++) {
  const item = items[i];
  const candidateData = normalized[i]?.json || {};

  let ai = {};
  try {
    const raw = item.json?.choices?.[0]?.message?.content || '{}';
    const cleaned = raw.replace(/^```[a-z]*\n?/, '').replace(/```$/, '').trim();
    ai = JSON.parse(cleaned);
  } catch (err) {
    ai = {
      score: 0,
      classification: 'weak',
      summary: 'AI evaluation failed.',
      strengths: ['Unable to parse'],
      concerns: ['AI error: ' + err.message],
      recommend_interview: false
    };
  }

  output.push({ json: {
    candidateId:      candidateData.candidateId || '',
    name:             candidateData.name || '',
    email:            candidateData.email || '',
    phone:            candidateData.phone || '',
    role:             candidateData.role || '',
    resumeUrl:        candidateData.resumeUrl || '',
    linkedin:         candidateData.linkedin || '',
    expYears:         candidateData.expYears || '',
    extra1:           candidateData.extra1 || '',
    extra2:           candidateData.extra2 || '',
    aiScore:          ai.score || 0,
    aiClassification: (ai.classification || 'weak').toLowerCase(),
    aiSummary:        ai.summary || '',
    aiStrengths:      (ai.strengths || []).join(' | '),
    aiConcerns:       (ai.concerns || []).join(' | '),
    aiRecommend:      ai.recommend_interview || false
  }});
}

return output;

const allItems = $input.all();

const masterEmails = new Set();
const candidates = [];

for (const item of allItems) {
  if (item.json.candidateId) {
    candidates.push(item);
  } else {
    const email = (
      item.json['Email Address'] ||
      item.json.Email ||
      item.json.email ||
      ''
    ).toLowerCase().trim();
    if (email) masterEmails.add(email);
  }
}

if (candidates.length === 0) return [];

const seenThisRun = new Set();

return candidates.map(item => {
  // Try every possible email field
  const email = (
    item.json.email ||
    item.json['Email Address'] ||
    item.json.Email ||
    ''
  ).toLowerCase().trim();

  const alreadyInMaster = masterEmails.has(email);
  const alreadyInBatch  = seenThisRun.has(email);

  seenThisRun.add(email);

  // DEBUG: log what we're checking
  const debugInfo = {
    candidateEmail: email,
    masterEmailsList: [...masterEmails],
    alreadyInMaster,
    alreadyInBatch
  };

  return {
    json: {
      ...item.json,
      isDuplicate: alreadyInMaster || alreadyInBatch,
      duplicateReason: alreadyInMaster ? 'exists_in_master'
                     : alreadyInBatch  ? 'duplicate_in_batch'
                     : 'none',
      debugInfo
    }
  };
});

const items = $input.all();
const output = [];

for (const item of items) {
  const { role, name, expYears, extra1, extra2 } = item.json;
  const resumeText = item.json.text || 'Resume text not available.';

  let criteria = '';

  if (role === 'SWE') {
    criteria = [
      'EVALUATION CRITERIA FOR SOFTWARE ENGINEER:',
      '1. Technical depth: proficiency in ' + (extra1 || 'relevant languages/frameworks'),
      '2. System design: experience with scalable architecture, microservices, APIs',
      '3. Problem-solving: evidence of complex projects or open source contributions',
      '4. Code quality: mentions of testing, CI/CD, code review practices',
      '5. Growth trajectory: increasing scope of responsibilities over time',
      '6. Education: CS degree or equivalent self-taught evidence',
      '',
      'STRONG: 4+ years, strong tech stack match, measurable impact, system design evidence',
      'AVERAGE: 2-4 years, decent skills but gaps in depth or breadth',
      'WEAK: under 2 years, no relevant stack, no measurable achievements'
    ].join('\n');
  } else {
    criteria = [
      'EVALUATION CRITERIA FOR BUSINESS DEVELOPMENT MANAGER:',
      '1. Revenue impact: specific numbers (deals closed, pipeline, % growth)',
      '2. Industry fit: experience in ' + (extra1 || 'relevant industries'),
      '3. Deal size: largest deals (candidate stated: ' + (extra2 || 'not provided') + ')',
      '4. Relationship building: enterprise client management, stakeholder engagement',
      '5. Sales methodology: SPIN, Challenger, MEDDIC or similar frameworks',
      '6. Strategy: market expansion, partnerships, go-to-market planning',
      '',
      'STRONG: consistent quota attainment, large deals, strategic thinking',
      'AVERAGE: some sales experience but lacks specific metrics or enterprise exposure',
      'WEAK: no revenue numbers, purely administrative, no client-facing evidence'
    ].join('\n');
  }
  const roleTitle = role === 'SWE'
    ? 'Software Engineer at a fast-growing tech company'
    : 'Business Development Manager at a growing B2B company';
  const prompt = [
    'You are an expert hiring manager evaluating a candidate for: ' + roleTitle + '.',
    '',
    'CANDIDATE: ' + name + ' | Experience: ' + expYears + ' years',
    '',
    'RESUME TEXT:',
    '---',
    resumeText.substring(0, 6000),  // Limit to 6000 chars to stay within token limits
    '---',
    '',
    criteria,
    '',
    'Respond ONLY with a valid JSON object, no markdown, no explanation:',
    '{',
    '  score: <integer 0-100>,',
    '  classification: strong|average|weak,',
    '  summary: <2-3 sentence assessment>,',
    '  strengths: [list of 3 strings],',
    '  concerns: [list of 2 strings],',
    '  recommend_interview: true|false',
    '}'
  ].join('\n');
  output.push({ json: { ...item.json, aiPrompt: prompt } });
}
  const cleanOutput = output.map(item => {
    const cleanPrompt = (item.json.aiPrompt || '')
      .replace(/[\r\n\t]/g, ' ')
      .replace(/\s+/g, ' ')
      .trim();
    return { json: { ...item.json, aiPrompt: cleanPrompt } };
  });

  return cleanOutput;
